// Gelen parametreleri kontrol et
const body = $input.item.json.body;

if (!body.exam_type || !body.subject || !body.topic || !body.difficulty) {
  throw new Error('Missing required parameters');
}

return { json: body };

const data = $input.item.json;

const difficultyLevel = {
  'Kolay': 'temel seviye, basit hesaplamalar',
  'Orta': 'orta seviye, birden fazla adım gerektirebilir',
  'Zor': 'ileri seviye, karmaşık problemler'
};

const prompt = `Sen bir ${data.exam_type} sınav sorusu oluşturma uzmanısın.

Konu: ${data.subject} - ${data.topic}
Zorluk: ${data.difficulty} (${difficultyLevel[data.difficulty]})

Aşağıdaki formatta bir çoktan seçmeli soru oluştur:

1. Soru metni (açık ve anlaşılır)
2. 5 seçenek (A, B, C, D, E)
3. Doğru cevap (harf olarak)
4. Detaylı çözüm açıklaması

Çıktı formatı JSON olmalı:
{
  "question_text": "...",
  "option_a": "...",
  "option_b": "...",
  "option_c": "...",
  "option_d": "...",
  "option_e": "...",
  "correct_answer": "A/B/C/D/E",
  "explanation": "..."
}

Sadece JSON döndür, başka açıklama ekleme.`;

return {
  json: {
    ...data,
    prompt: prompt
  }
};

